contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint v1, uint v2) public payable {
        // The contract is freshly deployed by the constructor, so it is uninitialized.
        // First call: set MinSum to v1.
        c.SetMinSum(v1); if (__ESBMC_reverted()) return;
        uint afterFirst = c.MinSum(); if (__ESBMC_reverted()) return;

        // Second call: overwrite MinSum with v2.
        c.SetMinSum(v2); if (__ESBMC_reverted()) return;
        uint afterSecond = c.MinSum(); if (__ESBMC_reverted()) return;

        assert(afterFirst == v1 && afterSecond == v2);
    }

    receive() external payable {}
}

